+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final String INVALID_EMAIL =
+            "Enter a valid e-mail address";
+
+    private final ContactMessageStore messageStore;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages =
+            new Grid<>(ContactMessage.class, false);
+    private final EmailValidator emailValidator =
+            new EmailValidator(INVALID_EMAIL);
+
+    public ContactView(ContactMessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        setWidthFull();
+        setMaxWidth("960px");
+        getStyle().set("margin", "0 auto");
+
+        RouterLink about = new RouterLink("About", AboutView.class);
+
+        FormLayout form = new FormLayout();
+        form.setAutoResponsive(true);
+        form.setExpandColumns(true);
+        form.setExpandFields(true);
+        form.setMaxColumns(3);
+        form.addFormRow(name, email, phone);
+        form.add(message, 3);
+
+        name.setTestId("contact-name");
+        email.setTestId("contact-email");
+        phone.setTestId("contact-phone");
+        message.setTestId("contact-message");
+        send.setTestId("contact-send");
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+
+        name.addValueChangeListener(event -> enableSendAfterEdit());
+        email.addValueChangeListener(event -> enableSendAfterEdit());
+        phone.addValueChangeListener(event -> enableSendAfterEdit());
+        message.addValueChangeListener(event -> enableSendAfterEdit());
+
+        send.addClickListener(event -> send());
+        send.addClickShortcut(Key.ENTER);
+
+        messages.addColumn(ContactMessage::name).setHeader("Name");
+        messages.addColumn(ContactMessage::message).setHeader("Message");
+        messages.setItems(messageStore.findAll());
+        messages.setAllRowsVisible(true);
+        messages.setWidthFull();
+
+        add(new H1("Contact"), about, form, send, messages);
+    }
+
+    private void enableSendAfterEdit() {
+        if (!send.isEnabled()) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void send() {
+        if (!validateForm()) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(name.getValue(), email.getValue(),
+                phone.getValue(), message.getValue()));
+        messages.setItems(messageStore.findAll());
+
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+
+        Notification.show("Message sent");
+    }
+
+    private boolean validateForm() {
+        clearValidation(name);
+        clearValidation(email);
+        clearValidation(message);
+
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            invalidate(name, "Name is required");
+            valid = false;
+        }
+
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        if (!emailValue.isEmpty()) {
+            if (emailValidator.apply(emailValue, new ValueContext(email))
+                    .isError()) {
+                invalidate(email, INVALID_EMAIL);
+                valid = false;
+            }
+        } else if (phoneValue.isEmpty()) {
+            invalidate(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        String messageValue = message.getValue();
+        if (messageValue.isBlank()) {
+            invalidate(message, "Message is required");
+            valid = false;
+        } else if (messageValue.codePoints().count() > 500) {
+            invalidate(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private static void invalidate(HasValidationProperties field,
+            String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private static void clearValidation(HasValidationProperties field) {
+        field.setInvalid(false);
+        field.setErrorMessage(null);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            navigation.cancel();
+            dialog.close();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+
+        dialog.add(new Paragraph(
+                "You have entered information that has not been sent."));
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+
+    private boolean hasInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty()
+                || !message.isEmpty();
+    }
+}
